export const PRODUCTS: Product[] = ALL_PRODUCTS.filter((product) => product.category === 'wrap');

export const WRAP_BRAND_ORDER = ['3M', 'Avery Dennison', 'KPMF', 'Metamark', 'ORAFOL', 'Arlon', 'Mactac'] as const;
export const WRAP_FINISH_ORDER = ['Gloss', 'High Gloss', 'Gloss Metallic', 'Gloss Pearl', 'ColorFlow Gloss', 'Satin', 'Satin Metallic', 'Satin Pearl', 'Matte', 'Matte Metallic', 'Color Flip', '3D Carbon'] as const;
const wrapBrandRank = (brand: string) => { const index = WRAP_BRAND_ORDER.indexOf(brand as typeof WRAP_BRAND_ORDER[number]); return index < 0 ? 999 : index; };
const wrapFinishRank = (finish?: string) => { const index = WRAP_FINISH_ORDER.indexOf((finish || '') as typeof WRAP_FINISH_ORDER[number]); return index < 0 ? 999 : index; };
export const WRAP_PRODUCTS: Product[] = PRODUCTS.filter((product) => product.category === 'wrap').sort((a,b) => wrapBrandRank(a.brand)-wrapBrandRank(b.brand) || wrapFinishRank(a.finish)-wrapFinishRank(b.finish) || (a.color || '').localeCompare(b.color || ''));

const CATEGORIES: {id:ProductCategory;label:string}[] = [
  {id:'all',label:'Сите бои'}, {id:'wrap',label:'Car Wrap'},
];
const publicBrandLabel = (brand: string) => brand.toUpperCase() === 'XPEL' ? 'TINTOLOGY' : brand;
const CATEGORY_LABEL: Record<Exclude<ProductCategory,'all'>,string> = {'automotive-tint':'Автомобилски фолии за стакла',ppf:'PPF заштита',wrap:'Фолии за промена на боја',architectural:'Архитектонски фолии'};
const UNIQUE = (values: (string|undefined)[]) => Array.from(new Set(values.filter(Boolean) as string[])).sort((a,b)=>a.localeCompare(b));

export default function ProductCatalog() {
  const [category,setCategory] = useState<ProductCategory>('all');
  const [query,setQuery] = useState('');
  const [brand,setBrand] = useState('all');
  const [color,setColor] = useState('all');
  const [finish,setFinish] = useState('all');
  const [expanded,setExpanded] = useState<string|null>(null);
  const [showFilters,setShowFilters] = useState(true);
  const [publicPrices,setPublicPrices] = useState<Record<string, number>>({});
  useEffect(() => { fetch('/api/catalog-prices').then(r => r.ok ? r.json() : {}).then(data => setPublicPrices(data || {})).catch(() => {}); }, []);
  const brands = useMemo(()=>[...WRAP_BRAND_ORDER.filter(b=>PRODUCTS.some(p=>p.brand===b)),...UNIQUE(PRODUCTS.map(p=>p.brand)).filter(b=>!WRAP_BRAND_ORDER.includes(b as any))],[]);
  const colors = useMemo(()=>UNIQUE(PRODUCTS.filter(p=>category==='all'||p.category===category).map(p=>p.color)),[category]);
  const finishes = useMemo(()=>UNIQUE(PRODUCTS.filter(p=>category==='all'||p.category===category).map(p=>p.finish)),[category]);
  const filtered = useMemo(()=>PRODUCTS.filter(p=>(category==='all'||p.category===category)&&(brand==='all'||p.brand===brand)&&(color==='all'||p.color===color)&&(finish==='all'||p.finish===finish)&&`${p.name} ${p.brand} ${p.series} ${p.code||''} ${p.description} ${p.specs.join(' ')} ${p.color||''} ${p.finish||''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.category==='wrap'&&b.category==='wrap'?(wrapBrandRank(a.brand)-wrapBrandRank(b.brand)||wrapFinishRank(a.finish)-wrapFinishRank(b.finish)||(a.color||'').localeCompare(b.color||'')):0),[category,brand,color,finish,query]);
  const clear = () => {setCategory('all');setBrand('all');setColor('all');setFinish('all');setQuery('');setExpanded(null);};
  return <section id="product-catalog" className="py-20 border-t border-[#1c1c28] bg-[#090b11]">
    <div className="mx-auto max-w-7xl px-6 lg:px-8">
      <div className="max-w-3xl mb-10">
        <div className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.22em] text-blue-400 mb-3"><Layers3 className="h-4 w-4"/> TINTOLOGY WRAP COLLECTION</div>
        <h2 className="font-display text-3xl sm:text-4xl font-extrabold tracking-tight text-white">Каталог за Фолии</h2>
        <p className="mt-3 text-sm sm:text-base leading-relaxed text-slate-400">Избери Wrap фолија според производителот, бојата и завршната обработка. Отвори варијанта за технички детали.</p>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_auto] gap-3 mb-4">
        <label className="relative"><Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-500"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Пребарај производ, бренд, боја или шифра..." className="w-full rounded-xl border border-slate-800 bg-[#111722] py-3.5 pl-11 pr-4 text-sm text-white outline-none focus:border-blue-500"/></label>
        <button type="button" onClick={()=>setShowFilters(v=>!v)} className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-800 bg-[#111722] px-5 py-3 text-sm font-semibold text-slate-200 hover:border-blue-500"><SlidersHorizontal className="h-4 w-4"/> Филтри <ChevronDown className={`h-4 w-4 transition-transform ${showFilters?'rotate-180':''}`}/></button>
      </div>
      {showFilters&&<div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3 mb-5 rounded-2xl border border-[#252b39] bg-[#0e131d] p-4">
        {[['Производител',brand,setBrand,brands],['Боја',color,setColor,colors],['Финиш / ефект',finish,setFinish,finishes]].map(([label,value,setter,options])=><label key={label as string} className="block"><span className="mb-1.5 block text-[11px] font-semibold uppercase tracking-wider text-slate-500">{label as string}</span><select value={value as string} onChange={e=>(setter as (v:string)=>void)(e.target.value)} className="w-full rounded-lg border border-slate-700 bg-[#151b27] px-3 py-3 text-sm text-white outline-none focus:border-blue-500"><option value="all">Сите</option>{(options as string[]).map(v=><option key={v} value={v}>{publicBrandLabel(v)}{label==='Производител'?` (${PRODUCTS.filter(p=>p.brand===v).length})`:''}</option>)}</select></label>)}
        <div className="flex items-end"><button type="button" onClick={clear} className="w-full rounded-lg border border-slate-700 px-3 py-3 text-sm font-semibold text-blue-200 hover:border-blue-500"><X className="mr-2 inline h-4 w-4"/> Исчисти филтри</button></div>
      </div>}
      <div className="flex flex-wrap gap-2 mb-7">{CATEGORIES.map(c=><button key={c.id} type="button" onClick={()=>{setCategory(c.id);setColor('all');setFinish('all');}} className={`rounded-full border px-4 py-2.5 text-xs font-semibold transition-colors ${category===c.id?'border-blue-400 bg-blue-500/15 text-blue-200':'border-slate-800 bg-[#11131b] text-slate-400 hover:border-slate-600 hover:text-white'}`}>{c.label}</button>)}</div>
      <div className="mb-4 flex items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs text-slate-400"><SlidersHorizontal className="h-4 w-4 text-blue-300"/><strong className="text-white">{filtered.length}</strong> производи</div>{(brand!=='all'||color!=='all'||finish!=='all'||query||category!=='all')&&<button type="button" onClick={clear} className="text-xs font-semibold text-blue-300 hover:text-blue-200">Ресетирај пребарување</button>}</div>
      {/* Horizontal product rail: cards scroll left/right and never create a long vertical grid. */}
      <div className="flex w-full items-stretch gap-5 overflow-x-auto overflow-y-hidden pb-5 snap-x snap-mandatory overscroll-x-contain [scrollbar-width:thin] [scrollbar-color:#334155_transparent]">
        {filtered.map((p,index)=>{
          const Icon=p.category==='automotive-tint'?CarFront:p.category==='ppf'?ShieldCheck:p.category==='wrap'?Palette:Building2;
          const open=expanded===p.id;
          const showBrandHeading=category==='wrap'&&brand==='all'&&(index===0||filtered[index-1]?.brand!==p.brand);
          const brandCount=filtered.filter(item=>item.brand===p.brand).length;
          return <React.Fragment key={p.id}>{showBrandHeading&&<div className="flex w-48 shrink-0 snap-start flex-col justify-end rounded-2xl border border-[#293448] bg-gradient-to-br from-[#14243a] to-[#0b1019] p-5"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-blue-400">TINTOLOGY WRAP COLLECTION</p><h3 className="mt-2 text-xl font-extrabold text-white">{publicBrandLabel(p.brand)}</h3><span className="mt-2 text-xs font-semibold text-slate-400">{brandCount} варијанти</span><span className="mt-5 text-[11px] text-slate-500">Повлечи лево или десно</span></div>}<article className="w-[min(82vw,320px)] shrink-0 snap-start overflow-hidden rounded-2xl border border-[#252b39] bg-[#11151e] hover:border-blue-500/50 transition-colors">
            <div className="relative h-44 flex items-center justify-center overflow-hidden bg-[radial-gradient(ellipse_at_center,_rgba(37,99,235,.18),_rgba(10,14,22,.2)_65%)]">
              {p.image?<img src={p.image} alt={`${publicBrandLabel(p.brand)} ${p.name}`} className="h-full w-full object-cover" loading="lazy"/>:p.swatch?<div className="h-full w-full" style={{background:p.swatch}}><div className="h-full w-full bg-gradient-to-br from-white/15 via-transparent to-black/30"/></div>:<Icon className="h-12 w-12 text-blue-300/80"/>}
              {p.category==='wrap'&&p.image&&<span className="absolute top-3 left-3 rounded-full border border-white/20 bg-black/65 px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider text-white backdrop-blur">Пример на автомобил</span>}
              {p.finish&&<span className="absolute bottom-3 left-3 rounded-full border border-white/20 bg-black/65 px-3 py-1 text-[10px] font-bold uppercase tracking-wider text-white backdrop-blur">{p.finish}</span>}
            </div>
            <div className="p-5">
              <div className="mb-2 flex items-center justify-between gap-3"><span className="text-[10px] font-bold uppercase tracking-[.16em] text-blue-300">{publicBrandLabel(p.brand)} · {p.series}</span><span className="text-right text-[10px] text-slate-500">{CATEGORY_LABEL[p.category]}</span></div>
              <h3 className="text-lg font-bold text-white">{p.name}</h3>
              <div className="mt-2 text-sm font-bold text-blue-200">{publicPrices[p.id] ? `${Number(publicPrices[p.id]).toLocaleString('mk-MK')} ден.` : 'Цена на барање'}</div>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{p.description}</p>
              {p.color&&<div className="mt-3 flex items-center gap-2 text-xs text-slate-300"><span className="h-4 w-4 rounded-full border border-white/25" style={{background:p.swatch||'#444'}}/> Боја: {p.color}</div>}
              {p.code&&<div className="mt-2 text-[11px] text-slate-500">Код на производител: {p.code}</div>}
              <button type="button" onClick={()=>setExpanded(open?null:p.id)} className="mt-4 w-full rounded-lg border border-slate-700 px-4 py-2.5 text-xs font-semibold text-slate-200 hover:border-blue-500 hover:text-blue-200">{open?'Сокриј детали':'Технички детали'}</button>
              {open&&<div className="mt-4 border-t border-slate-800 pt-4"><ul className="space-y-2">{p.specs.map((s,i)=><li key={i} className="flex gap-2 text-xs leading-relaxed text-slate-300"><span className="text-blue-400">•</span>{s}</li>)}</ul>{p.techUrl&&<a href={p.techUrl} target="_blank" rel="noreferrer" className="mt-4 inline-flex text-xs font-semibold text-blue-300 hover:text-blue-200">Технички каталог на производителот ↗</a>}</div>}
            </div>
          </article></React.Fragment>;
        })}
      </div>
      {filtered.length===0&&<div className="rounded-xl border border-dashed border-slate-700 py-14 text-center text-sm text-slate-500">Нема производи што одговараат на пребарувањето.</div>}
      <div className="mt-8 flex items-start gap-3 rounded-xl border border-blue-900/40 bg-blue-950/15 p-4 text-xs leading-relaxed text-slate-400"><Info className="h-4 w-4 shrink-0 text-blue-300"/><span>Боите на екранот се ориентативни и може да се разликуваат од реалниот материјал поради осветлување, екран и печатење. За точна нијанса користи физички примерок. Достапноста и можноста за нарачка се потврдуваат пред монтажа.</span></div>
    </div>
  </section>;
}
